{
  "word": "空洞",
  "reading": "くうどう",
  "definition_simple": "中がからっぽになっていること。またはその空間。",
  "definition_standard": "内部に何もなく、ぽっかりと空間が広がっていること。また、その空間や洞穴。",
  "examples": [
    {
      "japanese": "地盤沈下の原因を調べたら、地下に大きな空洞が見つかった。",
      "reading": "じばんちんかのげんいんをしらべたら、ちかにおおきなくうどうがみつかった。",
      "english": "When investigating the cause of the ground subsidence, a large cavity was found underground."
    },
    {
      "japanese": "この木の幹は古くなって、中はすっかり空洞になっている。",
      "reading": "このきのかみはふるくなって、なかはすっかりくうどうになっている。",
      "english": "The trunk of this tree is old, and the inside is completely hollow."
    },
    {
      "japanese": "大切な友人を失って以来、心にぽっかりと空洞ができたようだ。",
      "reading": "たいせつなゆうじんをうしなっていから、こころにぽっかりとくうどうができたようだ。",
      "english": "Ever since I lost my dear friend, it feels like a void has opened up in my heart."
    }
  ]
}
